import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n = Integer.parseInt(br.readLine());
        double[][] p = new double[n][n];

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int v = Integer.parseInt(st.nextToken());
                p[i][j] = v / 100.0;
            }
        }

        long[] mask = new long[n];
        for (int i = 0; i < n; i++) {
            long m = 0;
            for (int j = 0; j < (1 << n); j++) {
                if (((j >> i) & 1) == 0) {
                    m |= (1L << j);
                }
            }
            mask[i] = m;
        }

        Map<Long, Double> dp = new HashMap<>();
        dp.put(1L, 1.0);

        for (int i = 0; i < n; i++) {
            Map<Long, Double> new_dp = new HashMap<>();
            for (Map.Entry<Long, Double> state : dp.entrySet()) {
                long stateMask = state.getKey();
                double stateProb = state.getValue();

                for (int j = 0; j < (1 << n); j++) {
                    double prob = 1.0;
                    long res = 0;
                    for (int k = 0; k < n; k++) {
                        if (((j >> k) & 1) == 1) {
                            prob *= p[i][k];
                            res |= (stateMask & mask[k]) << (1 << k);
                        } else {
                            prob *= 1 - p[i][k];
                        }
                    }
                    new_dp.put(res, new_dp.getOrDefault(res, 0.0) + stateProb * prob);
                }
            }
            dp = new_dp;
        }

        double result = dp.getOrDefault((1L << n) - 1, 0.0);
        System.out.printf("%.9f\n", result);
    }
}
